/**
 * Prove every clip was generated in the intended voice, from the FILENAME.
 *
 * The manifest's `voice` field is a label the generator wrote next to the
 * entry. It is useful, but it is an assertion, not evidence: a wrong label and
 * a wrong recording look identical in it.
 *
 * The filename is evidence. It is sha1(version::speaker::voiceId::text)
 * truncated to 16 characters, so the voice id is baked into it. Recompute that
 * hash with the expected voice and it either matches the file the entry points
 * at or it does not - and if it does not, that audio was generated by a
 * different voice whatever the label says.
 *
 *   node scripts/audit-every-clip-is-emma.mjs
 *
 * Exits non-zero if any clip fails, is missing from disk, or carries a
 * different voice id.
 */
import { readFile, access } from "node:fs/promises";
import { createHash } from "node:crypto";

const generator = await readFile("scripts/elevenlabs-generate-narration.mjs", "utf8");

const VERSION = (generator.match(/const GENERATION_VERSION = "([^"]+)"/) || [])[1];
const voiceBlock = generator.match(/const VOICE = \{[\s\S]*?\n\};/)[0];
const VOICE = {};
for (const m of voiceBlock.matchAll(/(\w+):\s*\{\s*id:\s*"([^"]+)",\s*name:\s*"([^"]+)"/g)) {
  VOICE[m[1]] = { id: m[2], name: m[3] };
}
if (!VERSION || !Object.keys(VOICE).length) {
  console.error("could not read the generator's version or voice map");
  process.exit(2);
}

console.log(`generation version : ${VERSION}`);
for (const [k, v] of Object.entries(VOICE)) console.log(`  ${k.padEnd(9)} -> ${v.name}  ${v.id}`);

const joinBlock = (lines) =>
  lines.map((l) => l.trim()).filter(Boolean).join(" ").replace(/\s+/g, " ").trim();

const hashKey = (speaker, voiceId, text) =>
  createHash("sha1").update(`${VERSION}::${speaker}::${voiceId}::${text}`).digest("hex").slice(0, 16);

const manifest = JSON.parse(await readFile("public/audio/voice/manifest.json", "utf8"));

let ok = 0, missingFile = 0;
const wrongVoice = [];
const labelLies = [];

for (const e of manifest.entries) {
  const expected = VOICE[e.speaker];
  if (!expected) { wrongVoice.push({ e, why: `unknown speaker "${e.speaker}"` }); continue; }

  const lines = e.lines && e.lines.length ? e.lines : [e.text];
  const text = joinBlock(lines);
  const key = hashKey(e.speaker, expected.id, text);

  // the file this entry points at must be the one THIS voice would produce
  if (!e.file.endsWith(`${key}.mp3`)) {
    wrongVoice.push({ e, why: `file ${e.file.split("/").pop()} is not what ${expected.name} would produce (${key}.mp3)` });
    continue;
  }
  // and the label must agree with the map
  if (e.voice !== expected.name) labelLies.push({ e, why: `labelled "${e.voice}" but hashed as ${expected.name}` });

  try { await access("public" + e.file); ok++; }
  catch { missingFile++; wrongVoice.push({ e, why: "file missing from disk" }); }
}

console.log(`\nentries checked        : ${manifest.entries.length}`);
console.log(`hash matches the voice : ${ok}`);
console.log(`missing from disk      : ${missingFile}`);
console.log(`wrong voice            : ${wrongVoice.length - missingFile}`);
console.log(`label disagrees w/ hash: ${labelLies.length}`);

const byName = {};
for (const e of manifest.entries) byName[e.voice] = (byName[e.voice] || 0) + 1;
console.log(`\nvoices in the manifest : ${JSON.stringify(byName)}`);

if (wrongVoice.length || labelLies.length) {
  for (const w of [...wrongVoice, ...labelLies].slice(0, 10)) {
    console.error(`  - ${w.why}\n      "${(w.e.text || "").slice(0, 70)}"`);
  }
  process.exit(1);
}
console.log("\nevery clip's filename proves it was generated by the voice it claims.");
